#include <iostream>

int main() {
    int grade{0};
    if (std::cin >> grade) {
        // Double-selection if...else
        if (grade >= 60) {
            std::cout << "Passed\n";
        } else {
            std::cout << "Failed\n";
        }

        // Ternary conditional expression
        std::cout << "Result: " << (grade >= 60 ? "Passed" : "Failed") << "\n";
    }
    return 0;
}

#include <iostream>

int main() {
    int studentGrade{0};
    int x{6};
    int y{3};

    if (std::cin >> studentGrade) {
        // Nested if...else ladder with early exit
        if (studentGrade >= 90) {
            std::cout << "Grade: A\n";
        } else if (studentGrade >= 80) {
            std::cout << "Grade: B\n";
        } else if (studentGrade >= 70) {
            std::cout << "Grade: C\n";
        } else if (studentGrade >= 60) {
            std::cout << "Grade: D\n";
        } else {
            std::cout << "Grade: F\n";
        }

        // Dangling-else resolved with explicit braces
        if (x > 5) {
            if (y > 5) {
                std::cout << "x and y are > 5\n";
            }
        } else {
            std::cout << "x is <= 5\n";
        }
    }
    return 0;
}
